namespace RecipeShare.Services;

public class RecipeCategory
{
    public string Slug { get; set; } = "";
    public string Name { get; set; } = "";
    public string Icon { get; set; } = "";
    public string Description { get; set; } = "";
}

public class RecipeModel
{
    public int Id { get; set; }
    public string Title { get; set; } = "";
    public string CategorySlug { get; set; } = "";
    public string Ingredients { get; set; } = "";
    public string Steps { get; set; } = "";
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public class RecipeService
{
    private readonly List<RecipeCategory> _categories;
    private readonly List<RecipeModel> _recipes;
    private readonly Dictionary<int, List<int>> _ratings = new();
    private int _nextId;

    public RecipeService()
    {
        _categories = new List<RecipeCategory>
        {
            new() { Slug = "breakfast", Name = "Breakfast", Icon = "🥞", Description = "Start your day right with morning favorites." },
            new() { Slug = "lunch", Name = "Lunch", Icon = "🥗", Description = "Midday meals from salads to sandwiches." },
            new() { Slug = "dinner", Name = "Dinner", Icon = "🍝", Description = "Hearty evening dishes for the whole family." },
            new() { Slug = "desserts", Name = "Desserts", Icon = "🍰", Description = "Sweet treats to finish any meal." },
            new() { Slug = "snacks", Name = "Snacks", Icon = "🍿", Description = "Quick bites for any time of day." },
        };

        _recipes = new List<RecipeModel>
        {
            new() { Id = 1, Title = "Classic Pancakes", CategorySlug = "breakfast",
                Ingredients = "2 cups flour\n2 eggs\n1½ cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt\nButter for cooking",
                Steps = "1. Mix dry ingredients in a bowl.\n2. Whisk eggs and milk together, then combine with dry mix.\n3. Heat a buttered pan over medium heat.\n4. Pour ¼ cup batter per pancake.\n5. Flip when bubbles form on the surface.\n6. Serve with maple syrup." },
            new() { Id = 2, Title = "Avocado Toast", CategorySlug = "breakfast",
                Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\n1 tbsp lemon juice",
                Steps = "1. Toast bread until golden.\n2. Mash avocado with lemon juice, salt, and pepper.\n3. Spread on toast.\n4. Sprinkle with red pepper flakes." },
            new() { Id = 3, Title = "Caesar Salad", CategorySlug = "lunch",
                Ingredients = "1 head romaine lettuce\n½ cup croutons\n¼ cup parmesan cheese\nCaesar dressing\nGrilled chicken (optional)",
                Steps = "1. Wash and chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Top with croutons and shaved parmesan.\n4. Add grilled chicken if desired." },
            new() { Id = 4, Title = "Spaghetti Bolognese", CategorySlug = "dinner",
                Ingredients = "400g spaghetti\n500g ground beef\n1 onion, diced\n2 cloves garlic\n400g crushed tomatoes\n2 tbsp tomato paste\nOlive oil\nSalt, pepper, Italian herbs",
                Steps = "1. Cook spaghetti according to package directions.\n2. Sauté onion and garlic in olive oil.\n3. Add ground beef and brown thoroughly.\n4. Stir in tomatoes, paste, and seasonings.\n5. Simmer for 20 minutes.\n6. Serve sauce over spaghetti." },
            new() { Id = 5, Title = "Chocolate Chip Cookies", CategorySlug = "desserts",
                Ingredients = "2¼ cups flour\n1 cup butter, softened\n¾ cup sugar\n¾ cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
                Steps = "1. Preheat oven to 375°F (190°C).\n2. Cream butter and sugars.\n3. Beat in eggs and vanilla.\n4. Mix in flour and baking soda.\n5. Fold in chocolate chips.\n6. Drop spoonfuls onto baking sheet.\n7. Bake 9-11 minutes until golden." },
            new() { Id = 6, Title = "Trail Mix", CategorySlug = "snacks",
                Ingredients = "1 cup almonds\n1 cup cashews\n½ cup raisins\n½ cup dried cranberries\n½ cup chocolate chips\n½ cup sunflower seeds",
                Steps = "1. Combine all ingredients in a large bowl.\n2. Toss to mix evenly.\n3. Store in an airtight container." },
        };

        _nextId = _recipes.Max(r => r.Id) + 1;
    }

    public IReadOnlyList<RecipeCategory> GetCategories() => _categories.AsReadOnly();

    public RecipeCategory? GetCategory(string slug) =>
        _categories.FirstOrDefault(c => c.Slug == slug);

    public IReadOnlyList<RecipeModel> GetRecipesByCategory(string categorySlug) =>
        _recipes.Where(r => r.CategorySlug == categorySlug).ToList().AsReadOnly();

    public RecipeModel? GetRecipe(int id) =>
        _recipes.FirstOrDefault(r => r.Id == id);

    public void AddRecipe(RecipeModel recipe)
    {
        recipe.Id = _nextId++;
        _recipes.Add(recipe);
    }

    public void AddRating(int recipeId, int stars)
    {
        if (stars < 1 || stars > 5) return;
        var recipe = GetRecipe(recipeId);
        if (recipe is null) return;

        if (!_ratings.ContainsKey(recipeId))
            _ratings[recipeId] = new List<int>();

        _ratings[recipeId].Add(stars);
        recipe.RatingCount = _ratings[recipeId].Count;
        recipe.AverageRating = _ratings[recipeId].Average();
    }
}

@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService

<div class="star-rating d-inline-flex align-items-center gap-2">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _selectedRating ? "filled" : "")"
              @onclick="() => Rate(star)"
              role="button"
              title="Rate @star star@(star > 1 ? "s" : "")">
            @(star <= _selectedRating ? "★" : "☆")
        </span>
    }
    <span class="text-muted ms-2">
        @if (_recipe is not null && _recipe.RatingCount > 0)
        {
            <text>@_recipe.AverageRating.ToString("0.0") (@_recipe.RatingCount rating@(_recipe.RatingCount != 1 ? "s" : ""))</text>
        }
        else
        {
            <text>No ratings yet</text>
        }
    </span>
</div>

@code {
    [Parameter, EditorRequired]
    public int RecipeId { get; set; }

    private int _selectedRating;
    private RecipeModel? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeService.GetRecipe(RecipeId);
    }

    private void Rate(int stars)
    {
        _selectedRating = stars;
        RecipeService.AddRating(RecipeId, stars);
        _recipe = RecipeService.GetRecipe(RecipeId);
    }
}

.star {
    font-size: 1.5rem;
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
    user-select: none;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

