@page "/submit"
@rendermode InteractiveServer
@using RecipeShare.Services
@inject RecipeService RecipeService
@inject NavigationManager Navigation

<PageTitle>Submit a Recipe — RecipeShare</PageTitle>

<h1>📝 Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <strong>Recipe submitted!</strong> Your recipe has been added.
        <a href="recipe/@_submittedId">View it here</a>.
    </div>
}

<EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="submit-recipe">
    <DataAnnotationsValidator />
    <ValidationSummary class="text-danger" />

    <div class="mb-3">
        <label for="title" class="form-label">Recipe Title</label>
        <InputText id="title" @bind-Value="_model.Title" class="form-control" placeholder="e.g., Grandma's Apple Pie" />
        <ValidationMessage For="() => _model.Title" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="category" class="form-label">Category</label>
        <InputSelect id="category" @bind-Value="_model.CategorySlug" class="form-select">
            <option value="">— Select a category —</option>
            @foreach (var cat in RecipeService.GetCategories())
            {
                <option value="@cat.Slug">@cat.Icon @cat.Name</option>
            }
        </InputSelect>
        <ValidationMessage For="() => _model.CategorySlug" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="ingredients" class="form-label">Ingredients</label>
        <InputTextArea id="ingredients" @bind-Value="_model.Ingredients" class="form-control" rows="5"
                       placeholder="One ingredient per line" />
        <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
    </div>

    <div class="mb-3">
        <label for="steps" class="form-label">Steps</label>
        <InputTextArea id="steps" @bind-Value="_model.Steps" class="form-control" rows="6"
                       placeholder="Describe each step" />
        <ValidationMessage For="() => _model.Steps" class="text-danger" />
    </div>

    <button type="submit" class="btn btn-success">Submit Recipe</button>
    <a href="/" class="btn btn-outline-secondary ms-2">Cancel</a>
</EditForm>

@code {
    private SubmitRecipeModel _model = new();
    private bool _submitted;
    private int _submittedId;

    private void HandleSubmit()
    {
        var recipe = new RecipeModel
        {
            Title = _model.Title,
            CategorySlug = _model.CategorySlug,
            Ingredients = _model.Ingredients,
            Steps = _model.Steps
        };
        RecipeService.AddRecipe(recipe);
        _submittedId = recipe.Id;
        _submitted = true;
        _model = new();
    }

    private class SubmitRecipeModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        [System.ComponentModel.DataAnnotations.StringLength(100, ErrorMessage = "Title must be 100 characters or fewer.")]
        public string Title { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a category.")]
        public string CategorySlug { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = "";

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = "";
    }
}

